sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
    var _pat = new PatientUtils();
    var _patrecord = _pat.fetchpatientdetailbyid('PAT0001093');
    gs.print("First Name: " + _patrecord.u_first_name);
    gs.print("Last Name: " + _patrecord.u_last_name);
    gs.print("Contact Number: " + _patrecord.u_contact_number);
    gs.print("Email: " + _patrecord.u_email);
    gs.print('---------------------------------------------------------')

    var _checvip = _pat.checkvip('PAT0001081');
    gs.print(_checvip);
    gs.print('---------------------------------------------------------')

    var _patientage = _pat.calage('PAT0001093');
    gs.print("Age is: " + _patientage);
    gs.print('---------------------------------------------------------')

    var _patinetAppt = _pat.patientappointment('0214c8f093626610ec38b2ddfaba105e');
    if (!_patinetAppt.hasNext()) {
        gs.print("No appointments found for patient.");
    } else {
        while (_patinetAppt.next()) {
            gs.print("Appointment Date: " + _patinetAppt.u_appointment_date);
            gs.print("Doctor: " + _patinetAppt.u_doctor.getDisplayValue());
            gs.print("Status: " + _patinetAppt.u_statis);
            gs.print('-------')

        }
    }
    gs.print('---------------------------------------------------------')

    var _med = _pat.patientmedication('0214c8f093626610ec38b2ddfaba105e');
    if (!_med.hasNext()) {
        gs.print("No medication found for patient.");
    } else {
        while (_med.next()) {
            gs.print("Medication Name: " + _med.u_medication_name);
            gs.print("Dosage: " + _med.u_dosage);
            gs.print("Frequency: " + _med.u_frequency);
            gs.print('-------')

        }
    }
    gs.print('---------------------------------------------------------')


    var labtest = _pat.patientlabtest('0214c8f093626610ec38b2ddfaba105e');
    while (labtest.next()) {
        gs.print("Patient ID: " + labtest.u_patient_id);
        gs.print("Test ID: " + labtest.number);
        gs.print("Schedule Date" + labtest.u_schedule_date);
        gs.print("Results: " + labtest.u_results);
        gs.print('-------')
    }
    gs.print('---------------------------------------------------------')

    var bill = _pat.patientbillingrecords('0214c8f093626610ec38b2ddfaba105e');
    while (bill.next()) {
        gs.print("Patient ID: " + bill.u_patient_id);
        gs.print("Total Amount: " + bill.u_total_amount);
        gs.print("Billing ID: " + bill.number);
        gs.print("Status: " + bill.u_status);

    }
    gs.print('---------------------------------------------------------')



})(current, previous);
